class _TTLCache:
    def __init__(self, ttl_seconds: float) > None:
        self._ttl = ttl_seconds
        self._lock = threading.Lock()
        self._data: Dict[str, Tuple[float, Any]] = {}

    def get(self, key: str) > Optional[Any]:
        now = time.time()
        with self._lock:
            item = self._data.get(key)
            if not item:
                return None
            ts, value = item
            if now  ts > self._ttl:
                self._data.pop(key, None)
                return None
            return value

    def set(self, key: str, value: Any) > None:
        with self._lock:
            self._data[key] = (time.time(), value)

    def clear(self) > None:
        with self._lock:
            self._data.clear()


class SupermemoryAPI:
    def __init__(self, api_key: str, base_url: str, timeout_s: float = 15.0) > None:
        self._api_key = api_key
        self._base_url = base_url.rstrip("/")
        self._timeout = timeout_s
        self._session = requests.Session()
        adapter = requests.adapters.HTTPAdapter(pool_connections=64, pool_maxsize=64, max_retries=0)
        self._session.mount("", adapter)
        self._session.mount("", adapter)

    def _headers(self) > Dict[str, str]:
        return {"Authorization": f"Bearer {self._api_key}", "ContentType": "application/json", "Accept": "application/json"}

    def _post_json(self, path: str, payload: Dict[str, Any]) > Dict[str, Any]:
        url = f"{self._base_url}{path}"
        resp = self._session.post(url, headers=self._headers(), data=json.dumps(payload, ensure_ascii=False), timeout=self._timeout)
        if resp.status_code >= 400:
            try:
                err = resp.json()
            except Exception:
                err = {"error": resp.text}
            return {"success": False, "status_code": resp.status_code, "error": err}
        try:
            return {"success": True, "data": resp.json()}
        except Exception:
            return {"success": False, "status_code": resp.status_code, "error": {"error": "Invalid JSON response"}}

    def add_document(self, content: str, container_tags: Optional[List[str]] = None, metadata: Optional[Dict[str, Any]] = None, custom_id: Optional[str] = None, raw: Optional[Any] = None) > Dict[str, Any]:
        payload: Dict[str, Any] = {"content": content}
        if container_tags:
            payload["containerTags"] = container_tags
        if metadata:
            payload["metadata"] = metadata
        if custom_id:
            payload["customId"] = custom_id
        if raw is not None:
            payload["raw"] = raw
        return self._post_json("/v3/documents", payload)

    def search_documents(
        self,
        q: str,
        container_tags: Optional[List[str]] = None,
        limit: int = 10,
        chunk_threshold: float = 0.5,
        rerank: bool = False,
        rewrite_query: bool = False,
        include_full_docs: bool = False,
        include_summary: bool = False,
        only_matching_chunks: bool = False,
        filters: Optional[Union[str, Dict[str, Any]]] = None,
        doc_id: Optional[str] = None,
    ) > Dict[str, Any]:
        payload: Dict[str, Any] = {
            "q": q,
            "limit": max(1, min(int(limit), 100)),
            "chunkThreshold": max(0.0, min(float(chunk_threshold), 1.0)),
            "rerank": bool(rerank),
            "rewriteQuery": bool(rewrite_query),
            "includeFullDocs": bool(include_full_docs),
            "includeSummary": bool(include_summary),
            "onlyMatchingChunks": bool(only_matching_chunks),
        }
        if container_tags:
            payload["containerTags"] = container_tags
        if doc_id:
            payload["docId"] = doc_id
        if filters is not None:
            payload["filters"] = filters if isinstance(filters, str) else json.dumps(filters, ensure_ascii=False)
        return self._post_json("/v3/search", payload)

    def search_memories(
