def _safe_str(value: Any) > str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False)
    except Exception:
        try:
            return str(value)
        except Exception:
            return ""


def _compact_json(obj: Any, max_chars: int) > str:
    s = json.dumps(obj, ensure_ascii=False, separators=(",", ":"), sort_keys=False)
    if max_chars > 0 and len(s) > max_chars:
        return s[:max_chars]
    return s


def _normalize_role(role: str) > str:
    r = (role or "").strip().lower()
    if r in ("user", "assistant", "system", "tool"):
        return r
    return "user"


def _build_memory_context(container_tag: str, query: str) > Tuple[str, Dict[str, Any]]:
    if not supermemory_client or not SUPERMEMORY_ENABLED:
        return "", {"success": False, "error": "SUPERMEMORY_API_KEY not configured"}

    profile_key = f"profile:{container_tag}:{query if SUPERMEMORY_PROFILE_Q_INCLUDES_SEARCH else ''}"
    cached = profile_cache.get(profile_key) if SUPERMEMORY_ENABLE_PROFILE_INJECTION else None

    profile_resp: Optional[Dict[str, Any]] = None
    if cached is not None:
        profile_resp = cached
    else:
        if SUPERMEMORY_ENABLE_PROFILE_INJECTION:
            q_for_profile = query if SUPERMEMORY_PROFILE_Q_INCLUDES_SEARCH else None
            profile_resp = supermemory_client.profile(container_tag=container_tag, q=q_for_profile)
            profile_cache.set(profile_key, profile_resp)

    memory_search_resp: Optional[Dict[str, Any]] = None
    doc_search_resp: Optional[Dict[str, Any]] = None

    if SUPERMEMORY_ENABLE_QUERY_SEARCH_INJECTION:
        include = {"documents": True, "relatedMemories": True, "summaries": True}
        search_mode = "hybrid" if SUPERMEMORY_ENABLE_HYBRID_SEARCH else "memories"
        memory_search_resp = supermemory_client.search_memories(
            q=query,
            container_tag=container_tag,
            limit=SUPERMEMORY_MEMORY_SEARCH_LIMIT,
            threshold=SUPERMEMORY_MEMORY_SEARCH_THRESHOLD,
            rerank=SUPERMEMORY_MEMORY_SEARCH_RERANK,
            rewrite_query=SUPERMEMORY_MEMORY_SEARCH_REWRITE,
            search_mode=search_mode,
            include=include,
        )
        doc_search_resp = supermemory_client.search_documents(
            q=query,
            container_tags=[container_tag],
            limit=SUPERMEMORY_DOC_SEARCH_LIMIT,
            chunk_threshold=SUPERMEMORY_DOC_SEARCH_CHUNK_THRESHOLD,
            rerank=SUPERMEMORY_DOC_SEARCH_RERANK,
            rewrite_query=SUPERMEMORY_DOC_SEARCH_REWRITE,
            include_full_docs=SUPERMEMORY_DOC_SEARCH_INCLUDE_FULL_DOCS,
            include_summary=SUPERMEMORY_DOC_SEARCH_INCLUDE_SUMMARY,
            only_matching_chunks=SUPERMEMORY_DOC_SEARCH_ONLY_MATCHING_CHUNKS,
        )

    static_facts: List[str] = []
    dynamic_facts: List[str] = []
    profile_search_results: List[Any] = []

    if profile_resp and profile_resp.get("success") and isinstance(profile_resp.get("data"), dict):
        data = profile_resp["data"]
        profile = data.get("profile") or {}
        if isinstance(profile, dict):
            s = profile.get("static")
            d = profile.get("dynamic")
            if isinstance(s, list):
                static_facts = [x for x in s if isinstance(x, str) and x.strip()]
            if isinstance(d, list):
                dynamic_facts = [x for x in d if isinstance(x, str) and x.strip()]
        sr = data.get("searchResults") or {}
        if isinstance(sr, dict):
            results = sr.get("results")
            if isinstance(results, list):
                profile_search_results = results

    memory_results: List[Dict[str, Any]] = []
    if memory_search_resp and memory_search_resp.get("success") and isinstance(memory_search_resp.get("data"), dict):
        data = memory_search_resp["data"]
        results = data.get("results")
        if isinstance(results, list):
            for r in results:
                if isinstance(r, dict):
                    memory_results.append(r)

    doc_results: List[Dict[str, Any]] = []
    if doc_search_resp and doc_search_resp.get("success") and isinstance(doc_search_resp.get("data"), dict):
        data = doc_search_resp["data"]
        results = data.get("results")
        if isinstance(results, list):
            for r in results:
                if isinstance(r, dict):
                    doc_results.append(r)

    parts: List[str] = []
    if static_facts:
        parts.append("USER_PROFILE_STATIC_FACTS:")
        for f in static_facts:
            parts.append(f" {f}")
    if dynamic_facts:
        parts.append("USER_PROFILE_DYNAMIC_CONTEXT:")
        for f in dynamic_facts:
            parts.append(f" {f}")

    def add_memory_result_block(title: str, results_list: List[Any], max_items: int = 50) > None:
        if not results_list:
            return
        parts.append(title)
        count = 0
        for r in results_list:
            if count >= max_items:
                break
            if isinstance(r, str):
                txt = r.strip()
                if txt:
                    parts.append(f" {txt}")
                    count += 1
                continue
            if isinstance(r, dict):
                mem = _safe_str(r.get("memory")).strip()
                chunk = _safe_str(r.get("chunk")).strip()
                similarity = r.get("similarity")
                meta = r.get("metadata") if isinstance(r.get("metadata"), dict) else {}
                source = _safe_str(meta.get("source")).strip()
                doc_titles: List[str] = []
                docs = r.get("documents")
                if isinstance(docs, list):
                    for d in docs[:3]:
                        if isinstance(d, dict):
                            t = _safe_str(d.get("title")).strip()
                            if t:
                                doc_titles.append(t)
                related: List[str] = []
                ctx = r.get("context") if isinstance(r.get("context"), dict) else {}
                parents = ctx.get("parents") if isinstance(ctx.get("parents"), list) else []
                children = ctx.get("children") if isinstance(ctx.get("children"), list) else []
                for p in parents[:2]:
                    if isinstance(p, dict):
                        pm = _safe_str(p.get("memory")).strip()
                        if pm:
                            related.append(f"parent: {pm}")
                for c in children[:2]:
                    if isinstance(c, dict):
                        cm = _safe_str(c.get("memory")).strip()
                        if cm:
                            related.append(f"child: {cm}")
                row = []
                if mem:
                    row.append(mem)
                elif chunk:
                    row.append(chunk)
                if similarity is not None:
                    try:
                        row.append(f"similarity={float(similarity):.4f}")
                    except Exception:
                        row.append(f"similarity={_safe_str(similarity)}")
                if source:
                    row.append(f"source={source}")
                if doc_titles:
                    row.append("docs=" + "; ".join(doc_titles))
                if related:
                    row.append("related=" + " | ".join(related))
                if row:
                    parts.append(" " + " | ".join(row))
                    count += 1

    add_memory_result_block("RELEVANT_MEMORIES_FROM_PROFILE_SEARCH:", profile_search_results, max_items=30)
    add_memory_result_block("RELEVANT_MEMORIES_SEARCH_RESULTS:", memory_results, max_items=50)

    if doc_results:
        parts.append("RELEVANT_DOCUMENT_CHUNKS:")
        count = 0
        for r in doc_results[:50]:
            if not isinstance(r, dict):
                continue
            document = r.get("document") if isinstance(r.get("document"), dict) else {}
            doc_title = _safe_str(document.get("title")).strip()
            doc_url = _safe_str(document.get("url")).strip()
            summary = _safe_str(document.get("summary")).strip()
            chunks = r.get("chunks") if isinstance(r.get("chunks"), list) else []
            best_chunks: List[str] = []
            for ch in chunks[:3]:
                if isinstance(ch, dict):
                    content = _safe_str(ch.get("content")).strip()
                    score = ch.get("score")
                    if content:
                        if score is not None:
                            try:
                                best_chunks.append(f"{content} (score={float(score):.4f})")
                            except Exception:
                                best_chunks.append(f"{content} (score={_safe_str(score)})")
                        else:
                            best_chunks.append(content)
            row = []
            if doc_title:
                row.append(doc_title)
            if doc_url:
                row.append(doc_url)
            if summary:
                row.append("summary=" + summary)
            if best_chunks:
                row.append("chunks=" + " || ".join(best_chunks))
            if row:
                parts.append(" " + " | ".join(row))
                count += 1
            if count >= 50:
                break

    context_text = "\n".join(parts).strip()
    if context_text and SUPERMEMORY_MAX_CONTEXT_CHARS > 0 and len(context_text) > SUPERMEMORY_MAX_CONTEXT_CHARS:
        context_text = context_text[:SUPERMEMORY_MAX_CONTEXT_CHARS]

    diagnostics = {"profile": profile_resp, "memory_search": memory_search_resp, "doc_search": doc_search_resp}
    return context_text, {"success": True, "diagnostics": diagnostics}


def exa_search(
    query: str,
    search_type: str = "auto",
    num_results: int = 100,
    include_domains: Optional[List[str]] = None,
    exclude_domains: Optional[List[str]] = None,
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    include_text: Optional[str] = None,
    exclude_text: Optional[str] = None,
    category: Optional[str] = None,
    user_location: Optional[str] = None,
    get_text: bool = True,
    get_highlights: bool = True,
    get_summary: bool = True,
    highlights_per_url: int = 3,
    num_sentences: int = 3,
) > Dict[str, Any]:
    if not exa_client:
        return {"error": "EXA_API_KEY not configured", "success": False}
    try:
        contents_config: Dict[str, Any] = {}
        if get_text:
            contents_config["text"] = True
        if get_highlights:
            contents_config["highlights"] = {"highlights_per_url": highlights_per_url, "num_sentences": num_sentences}
        if get_summary:
            contents_config["summary"] = True
        result = exa_client.search(
            query,
            contents=contents_config if contents_config else None,
            num_results=max(1, min(int(num_results), 100)),
            type=search_type,
            include_domains=include_domains,
            exclude_domains=exclude_domains,
            start_published_date=start_date,
            end_published_date=end_date,
            include_text=include_text,
            exclude_text=exclude_text,
            category=category,
            user_location=user_location,
        )
        results_data: List[Dict[str, Any]] = []
        for r in getattr(result, "results", []) or []:
            item: Dict[str, Any] = {
                "title": getattr(r, "title", "") or "",
                "url": getattr(r, "url", "") or "",
                "published_date": getattr(r, "published_date", "") or "",
                "author": getattr(r, "author", "") or "",
                "id": getattr(r, "id", "") or "",
            }
            txt = getattr(r, "text", None)
            if get_text and txt:
                item["text"] = txt
            highlights = getattr(r, "highlights", None)
            if get_highlights and highlights:
                item["highlights"] = highlights
            highlight_scores = getattr(r, "highlight_scores", None)
            if get_highlights and highlight_scores:
                item["highlight_scores"] = highlight_scores
            summary = getattr(r, "summary", None)
            if get_summary and summary:
                item["summary"] = summary
            score = getattr(r, "score", None)
            if score is not None:
                item["score"] = score
            results_data.append(item)
        return {"query": query, "search_type": search_type, "num_results": len(results_data), "results": results_data, "success": True}
    except Exception as e:
        return {"error": str(e), "success": False}


