def exa_multi_step_search(
    queries: List[str],
    search_type: str = "auto",
    num_results_per_query: int = 20,
    include_domains: Optional[List[str]] = None,
    exclude_domains: Optional[List[str]] = None,
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    category: Optional[str] = None,
    user_location: Optional[str] = None,
    get_text: bool = True,
    get_highlights: bool = True,
    get_summary: bool = True,
) > Dict[str, Any]:
    if not exa_client:
        return {"error": "EXA_API_KEY not configured", "success": False}
    try:
        all_results: List[Dict[str, Any]] = []
        seen_urls: set = set()
        for q in queries:
            if not q or not isinstance(q, str):
                continue
            search_result = exa_search(
                query=q,
                search_type=search_type,
                num_results=num_results_per_query,
                include_domains=include_domains,
                exclude_domains=exclude_domains,
                start_date=start_date,
                end_date=end_date,
                category=category,
                user_location=user_location,
                get_text=get_text,
                get_highlights=get_highlights,
                get_summary=get_summary,
            )
            if search_result.get("success") and search_result.get("results"):
                for r in search_result["results"]:
                    url = r.get("url", "")
                    if url and url not in seen_urls:
                        seen_urls.add(url)
                        r["source_query"] = q
                        all_results.append(r)
        return {"queries": queries, "total_results": len(all_results), "results": all_results[:100], "success": True}
    except Exception as e:
        return {"error": str(e), "success": False}


